module card_shuffle_counter(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] card_in,\n    input valid,\n    output reg [1:0] result,\n    output reg done\n);\n\n    // State Encoding\n    localparam IDLE    = 3'b000;\n    localparam COLLECT = 3'b001;\n    localparam CHECK_0 = 3'b010;\n    localparam CHECK_1 = 3'b011;\n    localparam CHECK_2 = 3'b100;\n    localparam DONE    = 3'b101;\n\n    // Internal Registers\n    reg [2:0] state;\n    reg [2:0] count;\n    reg [3:0] buffer [0:7];\n\n    // Combinational helper function to check if a range is sorted in the buffer\n    function automatic logic is_sorted_range(input [3:0] low, input [3:0] high, input [3:0] buf_in [0:7]);\n        logic [3:0] expected;\n        logic fail;\n        begin\n            expected = low;\n            fail = 1'b0;\n            for (int i = 0; i < 8; i++) begin\n                if (buf_in[i] >= low && buf_in[i] <= high) begin\n                    if (buf_in[i] != expected) fail = 1'b1;\n                    else expected = expected + 1;\n                end\n            end\n            if (expected != high + 1) fail = 1'b1;\n            return !fail;\n        end\n    endfunction\n\n    // Combinational flags\n    logic is_sorted_0;\n    logic is_1_shuffle;\n    logic is_2_shuffle;\n\n    // Check 0: Sorted (1, 2, 3, 4, 5, 6, 7, 8)\n    assign is_sorted_0 = (buffer[0] == 4'd1) && (buffer[1] == 4'd2) &&\n                         (buffer[2] == 4'd3) && (buffer[3] == 4'd4) &&\n                         (buffer[4] == 4'd5) && (buffer[5] == 4'd6) &&\n                         (buffer[6] == 4'd7) && (buffer[7] == 4'd8);\n\n    // Check 1: 1 Shuffle\n    // Exists k such that {1..k} is sorted in buffer and {k+1..8} is sorted in buffer\n    always_comb begin\n        is_1_shuffle = 1'b0;\n        for (int k = 1; k < 8; k++) begin\n            if (is_sorted_range(1, k, buffer) && is_sorted_range(k+1, 8, buffer)) begin\n                is_1_shuffle = 1'b1;\n            end\n        end\n    end\n\n    // Check 2: 2 Shuffles\n    // Exists split points s1, s2, s3 such that 4 ranges are sorted\n    // Range 1: 1..s1\n    // Range 2: s1+1..s2\n    // Range 3: s2+1..s3\n    // Range 4: s3+1..8\n    always_comb begin\n        is_2_shuffle = 1'b0;\n        for (int s1 = 1; s1 <= 5; s1++) begin\n            for (int s2 = s1 + 1; s2 <= 6; s2++) begin\n                for (int s3 = s2 + 1; s3 <= 7; s3++) begin\n                    if (is_sorted_range(1, s1, buffer) && \n                        is_sorted_range(s1 + 1, s2, buffer) && \n                        is_sorted_range(s2 + 1, s3, buffer) && \n                        is_sorted_range(s3 + 1, 8, buffer)) begin\n                        is_2_shuffle = 1'b1;\n                    end\n                end\n            end\n        end\n    end\n\n    // State Machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 0;\n            done <= 0;\n            result <= 0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 0;\n                    if (start) begin\n                        state <= COLLECT;\n                        count <= 0;\n                    end\n                end\n\n                COLLECT: begin\n                    if (valid) begin\n                        buffer[count] <= card_in;\n                        if (count == 7) begin\n                            state <= CHECK_0;\n                        end else begin\n                            count <= count + 1;\n                        end\n                    end\n                end\n\n                CHECK_0: begin\n                    if (is_sorted_0) begin\n                        result <= 0;\n                        state <= DONE;\n                    end else begin\n                        state <= CHECK_1;\n                    end\n                end\n\n                CHECK_1: begin\n                    if (is_1_shuffle) begin\n                        result <= 1;\n                        state <= DONE;\n                    end else begin\n                        state <= CHECK_2;\n                    end\n                end\n\n                CHECK_2: begin\n                    if (is_2_shuffle) begin\n                        result <= 2;\n                    end else begin\n                        result <= 3;\n                    end\n                    state <= DONE;\n                end\n\n                DONE: begin\n                    done <= 1;\n                    if (start) begin\n                        // Restart if start is asserted again\n                        state <= COLLECT;\n                        count <= 0;\n                        done <= 0;\n                    end\n                end\n            endcase\n        end\n    end\n\nendmodule